<script setup>
import { vSoftReveal } from '@/directives/softReveal'
import { computed, ref, watch, onMounted, onUnmounted } from 'vue'
import ProfileAvatar from './ProfileAvatar.vue'
import ProfileRewardDialog from './ProfileRewardDialog.vue'
const props=defineProps({tab:{type:String,default:'achievements'},profile:{type:Object,required:true},icons:{type:Array,default:()=>[]},unlocked:{type:Array,default:()=>[]},stars:{type:Number,default:0},own:Boolean,admin:Boolean,busy:Boolean,selectionReset:Number,cost:Function,saga:Function})
const emit=defineEmits(['tab','back','equip','gachapon','manage-icon'])
const search=ref(''),ownership=ref('all'),page=ref(1),selectedId=ref(''),showHelp=ref(false)
const catalog=computed(()=>props.icons.filter(icon=>props.tab==='manage'||(!icon.archived&&icon.visible!==false)||props.unlocked.includes(icon.id)))
const ownedCount=computed(()=>catalog.value.filter(icon=>props.unlocked.includes(icon.id)).length)
const filtered=computed(()=>catalog.value.filter(icon=>(ownership.value==='all'||(ownership.value==='owned')===props.unlocked.includes(icon.id))&&String(icon.name).toLocaleLowerCase('es').includes(search.value.toLocaleLowerCase('es'))).sort((a,b)=>Number(b.id===props.profile.selectedIcon)-Number(a.id===props.profile.selectedIcon)||Number(props.unlocked.includes(b.id))-Number(props.unlocked.includes(a.id))))
const pageSize=ref(12)
function resizeCollection(){pageSize.value=window.innerWidth<=760?(window.innerHeight<560?4:window.innerHeight<720?8:12):12}
onMounted(()=>{resizeCollection();window.addEventListener('resize',resizeCollection)})
onUnmounted(()=>window.removeEventListener('resize',resizeCollection))
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/pageSize.value)))
const visible=computed(()=>filtered.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value))
const selected=computed(()=>props.icons.find(icon=>icon.id===selectedId.value))
const tabs=computed(()=>[{id:'achievements',label:'Logros',icon:'fas fa-trophy'},{id:'collection',label:'Colección',icon:'fas fa-layer-group'},...(props.admin?[{id:'manage',label:'Administrar',icon:'fas fa-gear'}]:[])])
function inspect(icon){if(props.busy)return;if(props.tab==='manage')emit('manage-icon',icon);else selectedId.value=icon.id}
function equip(){if(selected.value&&props.own&&props.unlocked.includes(selected.value.id)){emit('equip',selected.value.id);selectedId.value=''}}
watch([search,ownership],()=>page.value=1)
watch(()=>[props.tab,props.selectionReset],()=>{page.value=1;selectedId.value='';search.value='';ownership.value='all'})
watch(pages,value=>page.value=Math.min(page.value,value))
</script>
<template>
<section v-soft-reveal="'.rewards-icons > button'" class="rewards-hub">
 <button type="button" class="back-link" @click="emit('back')">← Volver al perfil</button>
 <header class="hub-head"><h1>Logros y colección</h1><div v-if="own" class="wallet"><strong>★ {{ stars }} estrellas</strong><button type="button" :aria-expanded="showHelp" @click="showHelp=!showHelp">Cómo ganar estrellas</button></div></header>
 <p v-if="showHelp&&own" class="hub-help">Consigue estrellas leyendo noticias con recompensa. Cada noticia se recompensa una sola vez al completar el tiempo de lectura requerido.</p>
 <nav class="hub-tabs" aria-label="Recompensas"><button v-for="item in tabs" :key="item.id" type="button" :aria-current="tab===item.id?'page':undefined" :class="{active:tab===item.id}" @click="emit('tab',item.id)"><i :class="item.icon" aria-hidden="true"></i>{{ item.label }}</button></nav>
 <slot v-if="tab==='achievements'" name="achievements"/>
 <template v-else>
  <template v-if="tab==='manage'"><h2>Administrar logros</h2><slot name="management"/></template>
  <section class="collection-panel">
   <header class="catalog-head"><div><h2>{{ tab==='manage'?'Administrar iconos':'Colección de iconos' }}</h2><p>{{ ownedCount }} de {{ catalog.length }} conseguidos</p></div><button v-if="own&&tab==='collection'" type="button" class="collection-gacha" @click="emit('gachapon')">✦ Obtener icono</button></header>
   <div class="catalog-controls"><label><span class="sr-only">Buscar iconos</span><input v-model="search" placeholder="Buscar iconos" type="search"/></label><label><span class="sr-only">Mostrar iconos</span><select v-model="ownership"><option value="all">Todos</option><option value="owned">Obtenidos</option><option value="missing">Por conseguir</option></select></label></div>
   <div v-if="visible.length" class="rewards-icons"><button v-for="icon in visible" :key="icon.id" type="button" :class="{missing:!unlocked.includes(icon.id),equipped:profile.selectedIcon===icon.id}" @click="inspect(icon)"><ProfileAvatar :src="icon.src" :alt="icon.name" :effect="icon"/><strong>{{ icon.name }}</strong><small>{{ profile.selectedIcon===icon.id?'En uso':unlocked.includes(icon.id)?'Obtenido':'Por conseguir' }}</small></button></div>
   <p v-else class="catalog-empty">No hay iconos con este filtro.</p>
   <nav v-if="pages>1" class="catalog-pagination" aria-label="Páginas de iconos"><button type="button" :disabled="page===1" @click="page--">←</button><span aria-live="polite">{{ page }} / {{ pages }}</span><button type="button" :disabled="page===pages" @click="page++">→</button></nav>
  </section>
 </template>
 <ProfileRewardDialog v-if="selected" :result="{icon:selected}" inspect :own="own" :equipped="profile.selectedIcon===selected.id" :obtained="unlocked.includes(selected.id)" :saga="saga(selected)" :saving="busy" :stars="stars" :cost="cost" @close="selectedId=''" @use="equip" @gachapon="selectedId='';emit('gachapon')"/>
</section>
</template>
<style scoped>
.rewards-hub{max-width:1100px;margin:auto;color:var(--text-primary,#f8fafc);font-weight:400}.back-link{border:0;background:none;color:var(--accent,#a78bfa);font:inherit;font-size:12px;padding:0;cursor:pointer}.hub-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:18px 0}.hub-head h1{font-size:23px;line-height:1.3;margin:0}.wallet{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.wallet strong{font-size:13px;color:#fcd34d}.wallet button{border:0;background:none;color:var(--accent,#a78bfa);font-size:11px;cursor:pointer}.hub-help{padding:12px;background:#7c3aed10;border-radius:10px;font-size:12px;line-height:1.6}.hub-tabs{display:flex;gap:8px;border-bottom:1px solid var(--border,#a855f733);padding-bottom:12px;margin-bottom:16px}.hub-tabs button{display:flex;align-items:center;gap:7px;padding:9px 14px;border:1px solid var(--border,#a855f733);border-radius:10px;background:transparent;color:inherit;font:inherit;font-size:12px;cursor:pointer}.hub-tabs button.active{background:var(--accent,#7c3aed);color:white}.collection-panel{border:1px solid var(--border,#a855f733);background:var(--card-bg,#111324);border-radius:16px;padding:18px}.catalog-head{display:flex;justify-content:space-between;align-items:center;gap:12px}.catalog-head h2{font-size:18px;margin:0}.catalog-head p{font-size:12px;color:var(--text-secondary,#94a3b8);margin:5px 0 0}.collection-gacha{font:inherit;font-size:12px;padding:10px 12px;border:0;border-radius:10px;color:white;background:linear-gradient(110deg,#7c3aed,#a72ab7);cursor:pointer}.catalog-controls{display:flex;gap:10px;margin:16px 0}.catalog-controls label:first-child{flex:1}.catalog-controls label{min-width:0}.catalog-controls input,.catalog-controls select{box-sizing:border-box;width:100%;min-height:38px;border:1px solid var(--border,#a855f733);border-radius:9px;background:var(--surface,#101427);color:inherit;padding:8px 10px;font:inherit;font-size:12px}.rewards-icons{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px}.rewards-icons button{min-width:0;display:flex;flex-direction:column;align-items:center;gap:8px;padding:12px 6px;border:1px solid var(--border,#a855f733);border-radius:12px;background:#7c3aed05;color:inherit;font:inherit;cursor:pointer}.rewards-icons :deep(.profile-avatar-ui){--avatar-size:56px;--avatar-border:1px}.rewards-icons strong{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:1;overflow:hidden;max-width:100%;font-size:11px;font-weight:500;line-height:16px}.rewards-icons small{font-size:10px;color:#5ee7b9}.rewards-icons .missing :deep(.profile-avatar-ui){opacity:.48}.rewards-icons .missing small{color:var(--text-secondary,#94a3b8)}.rewards-icons .equipped{border-color:#a78bfa;background:#7c3aed14}.catalog-pagination{display:flex;justify-content:center;align-items:center;gap:16px;margin-top:16px;font-size:12px}.catalog-pagination button{width:38px;height:34px;border:1px solid var(--border,#a855f733);border-radius:8px;background:transparent;color:inherit;cursor:pointer}.catalog-pagination button:disabled{opacity:.3}.catalog-empty{padding:24px;text-align:center;font-size:13px;color:var(--text-secondary,#94a3b8)}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent,#a78bfa);outline-offset:2px}@media(max-width:760px){.hub-head{align-items:start;flex-direction:column;margin:12px 0}.hub-head h1{font-size:20px}.collection-panel{padding:12px}.catalog-head h2{font-size:16px}.rewards-icons{grid-template-columns:repeat(4,minmax(0,1fr));gap:7px}.rewards-icons :deep(.profile-avatar-ui){--avatar-size:46px}.rewards-icons button{padding:10px 4px;gap:5px}.catalog-controls{margin:12px 0;gap:7px}.catalog-controls select{max-width:130px}.collection-gacha{font-size:11px;padding:9px}.hub-tabs button{padding:8px 10px;font-size:11px}.hub-tabs{gap:5px}.catalog-head{align-items:start}}
</style>
